private func replanAfterDriftedIntents(
    _ drifted: Set<StageScope>,
    protected: Set<StageScope>,
    snapshot: DaemonSnapshot,
    observedFrames: [WindowID: Rect],
    excluded: Set<StageScope>
) -> MaintenanceTick {
    for scope in drifted { service.removeLayoutIntent(scope: scope) }
    lastCommandIntentAt = nil
    let remaining = protected.subtracting(drifted)
    let tick = applyPlan(from: snapshot, observedFrames: observedFrames, excluding: remaining.union(excluded))
    events.append(RoadieEvent(type: "command_intent_invalidated_by_manual_geometry", details: [
        "scopes": drifted.map(\.description).sorted().joined(separator: ","),
        "remainingProtectedScopes": remaining.map(\.description).sorted().joined(separator: ","),
        "commands": String(tick.commands)
    ]))
    return tick
}

